import{_ as e,o as d,c as a,ak as s}from"./chunks/framework.sV-XtlWr.js";const g=JSON.parse('{"title":"Piwi CLI","description":"Every command and flag of the piwi CLI that ships with @piwitests/reporter: init, skills, gate, report, select, run, probe, ai, codegen, preflight and bug.","frontmatter":{"title":"Piwi CLI","description":"Every command and flag of the piwi CLI that ships with @piwitests/reporter: init, skills, gate, report, select, run, probe, ai, codegen, preflight and bug.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/reference/cli.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/reference/cli.html"}],["meta",{"property":"og:title","content":"Piwi CLI | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Every command and flag of the piwi CLI that ships with @piwitests/reporter: init, skills, gate, report, select, run, probe, ai, codegen, preflight and bug."}]]},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md","lastUpdated":1790630787000}'),o={name:"reference/cli.md"};function i(r,t,n,c,l,h){return d(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="piwi-cli" tabindex="-1">Piwi CLI <a class="header-anchor" href="#piwi-cli" aria-label="Permalink to &quot;Piwi CLI&quot;">​</a></h1><p>The <code>@piwitests/reporter</code> package ships a command-line tool, <code>piwi</code>, for the things that happen <em>around</em> a test run: wiring a project up, gating a CI job on the dashboard&#39;s analysis, running a saved test selection, turning a recording into a spec, and managing AI-step artifacts and agent skills. This page is the reference for every command and flag; each command&#39;s own <code>--help</code> prints the same list.</p><h2 id="invoking-it" tabindex="-1">Invoking it <a class="header-anchor" href="#invoking-it" aria-label="Permalink to &quot;Invoking it&quot;">​</a></h2><p>Run it through the package name so <code>npx</code> resolves this package:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">comman</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [options]</span></span></code></pre></div><blockquote><p>The package is <code>@piwitests/reporter</code>; its command is <code>piwi</code>. A plain <code>npx piwi …</code> would fetch an unrelated <code>piwi</code> from npm — invoke it through the package name. Once the reporter is a project dependency, <code>npx piwi &lt;command&gt;</code> resolves the local binary and works too.</p></blockquote><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><a href="#init"><code>init</code></a></td><td>Wire a Playwright project up to a Piwi Dashboard</td></tr><tr><td><a href="#skills"><code>skills</code></a></td><td>Install the Piwi agent skills into this project</td></tr><tr><td><a href="#gate"><code>gate</code></a></td><td>Fail a CI job on the dashboard&#39;s analysis of a run</td></tr><tr><td><a href="#report"><code>report</code></a></td><td>Print a <a href="/features/quality-reports.html">quality report</a> as Markdown, PDF, HTML, CSV or JSON</td></tr><tr><td><a href="#select-run"><code>select</code></a></td><td>Print the Playwright args for a saved test selection</td></tr><tr><td><a href="#select-run"><code>run</code></a></td><td>Run a saved test selection with <code>playwright test</code></td></tr><tr><td><a href="#probe"><code>probe</code></a></td><td>Run the dashboard&#39;s probe plan and record what the suite noticed</td></tr><tr><td><a href="#ai"><code>ai</code></a></td><td>Manage committed natural-language AI-step artifacts</td></tr><tr><td><a href="#codegen"><code>codegen</code></a></td><td>Turn a steps file (a Piwi Picker recording) into a Playwright spec</td></tr><tr><td><a href="#preflight"><code>preflight</code></a></td><td>List the test locators your change breaks, and fix them</td></tr><tr><td><a href="#bug"><code>bug</code></a></td><td>Write a bug report&#39;s failing test into the project and run it once</td></tr></tbody></table><p>Several commands read connection settings from the environment as a fallback: <code>PIWI_DASHBOARD_URL</code> (dashboard URL), <code>PIWI_API_KEY</code> (API key), and <code>PIWI_PROJECT_NAME</code> (project). A flag always wins over its environment variable.</p><h2 id="init" tabindex="-1"><code>init</code> <a class="header-anchor" href="#init" aria-label="Permalink to &quot;`init`&quot;">​</a></h2><p>Wire a Playwright project up to a dashboard. It installs the reporter as a dev dependency, wraps <code>export default defineConfig(...)</code> with <a href="/guide/reporter.html#installing-via-wrapconfig"><code>wrapConfig(...)</code></a>, creates the <a href="/guide/capture-fixtures.html">capture-fixtures</a> file, records <code>PIWI_*</code> connection settings in <code>.env</code> / <code>.env.example</code> (and <code>.gitignore</code>), and installs the <a href="/features/agent-skills.html">agent skills</a>. <strong>Every step is idempotent</strong> — safe to re-run — and a config shape it will not rewrite is reported as <code>manual</code> with the exact change to make. See the <a href="/guide/getting-started.html#fast-path-one-command">one-command setup</a> in Getting started.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --server-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:3000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-project</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Flag</th><th>Description</th></tr></thead><tbody><tr><td><code>--server-url &lt;url&gt;</code></td><td>Dashboard URL to write into the config (env <code>PIWI_DASHBOARD_URL</code>, default <code>http://localhost:3000</code>)</td></tr><tr><td><code>--project &lt;name&gt;</code></td><td>Project name to report under (default: your package/folder name)</td></tr><tr><td><code>--api-key &lt;key&gt;</code></td><td>API key to write into <code>.env</code> (env <code>PIWI_API_KEY</code>). Omit to leave a <code>.env.example</code> placeholder you fill in yourself</td></tr><tr><td><code>--cwd &lt;path&gt;</code></td><td>Project root to operate on (default: current directory)</td></tr><tr><td><code>--skills &lt;list&gt;</code></td><td>Comma-separated skills to install, or <code>all</code> / <code>none</code> (default: the four workflow skills)</td></tr><tr><td><code>--skills-dir &lt;path&gt;</code></td><td>Directory to install skills into (default: <code>.claude/skills</code>)</td></tr><tr><td><code>--skills-only</code></td><td>Only install skills; do not touch the config or env</td></tr><tr><td><code>--no-skills</code></td><td>Configure the project but install no skills</td></tr><tr><td><code>--no-install</code></td><td>Do not run the package manager; record the dependency only</td></tr><tr><td><code>--force</code></td><td>Overwrite skill files that already exist</td></tr><tr><td><code>--dry-run</code></td><td>Report every change without writing anything</td></tr><tr><td><code>--json</code></td><td>Print the plan/result as JSON (for agents)</td></tr><tr><td><code>-h</code>, <code>--help</code></td><td>Show help</td></tr></tbody></table><h2 id="skills" tabindex="-1"><code>skills</code> <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;`skills`&quot;">​</a></h2><p>Install the Piwi <a href="/features/agent-skills.html">agent skills</a> into a project — agent-agnostic Markdown that lets a coding agent investigate failures, heal locators, and stabilize flaky tests. <code>init</code> installs these for you; use <code>skills</code> to add them to a project that already has the reporter, or to a different skills directory.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [names...] [options]</span></span></code></pre></div><p>The seven skills are <code>setup-piwi</code>, <code>investigate-failure</code>, <code>apply-locator-healing</code>, <code>stabilize-flaky-tests</code>, <code>run-the-right-tests</code>, <code>write-the-missing-test</code> and <code>fix-a-reported-bug</code>. <code>add</code> with no names installs all of them.</p><table tabindex="0"><thead><tr><th>Flag (for <code>add</code>)</th><th>Description</th></tr></thead><tbody><tr><td><code>--dir &lt;path&gt;</code></td><td>Directory to install into (default: <code>.claude/skills</code>)</td></tr><tr><td><code>--cwd &lt;path&gt;</code></td><td>Project root to operate on (default: current directory)</td></tr><tr><td><code>--force</code></td><td>Overwrite a skill file that already exists</td></tr><tr><td><code>--dry-run</code></td><td>Report what would be written without writing</td></tr><tr><td><code>--json</code></td><td>Print the results as JSON</td></tr></tbody></table><h2 id="gate" tabindex="-1"><code>gate</code> <a class="header-anchor" href="#gate" aria-label="Permalink to &quot;`gate`&quot;">​</a></h2><p>Fail a CI job on the dashboard&#39;s analysis of a run — the <a href="/guide/ci.html#blocking-a-merge">merge gate</a>. Point it at a run, give it at least one policy rule, and it exits non-zero when the rule is violated. The run defaults to <code>./piwi-run.json</code> (the reporter&#39;s <a href="/guide/ci.html#getting-the-run-url-back-out-of-ci">output file</a>) when present.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --max-new-regressions</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail-on-flaky</span></span></code></pre></div><p><strong>Exit codes:</strong> <code>0</code> satisfied · <code>1</code> violated · <code>2</code> could not evaluate.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Description</th></tr></thead><tbody><tr><td><code>--run-id &lt;id&gt;</code></td><td>Run id to evaluate</td></tr><tr><td><code>--from-file &lt;path&gt;</code></td><td>Read <code>runId</code> from the reporter&#39;s output JSON</td></tr><tr><td><code>--server-url &lt;url&gt;</code></td><td>Dashboard URL (env <code>PIWI_DASHBOARD_URL</code>)</td></tr><tr><td><code>--api-key &lt;key&gt;</code></td><td>API key (env <code>PIWI_API_KEY</code>)</td></tr><tr><td><code>--require-tag &lt;tags&gt;</code></td><td>Comma-separated; every test carrying the tag must pass</td></tr><tr><td><code>--max-failed &lt;n&gt;</code></td><td>Fail when more than <em>n</em> tests failed</td></tr><tr><td><code>--max-new-regressions &lt;n&gt;</code></td><td>Fail when more than <em>n</em> tests newly started failing</td></tr><tr><td><code>--max-new-flaky &lt;n&gt;</code></td><td>Fail when more than <em>n</em> tests newly became flaky</td></tr><tr><td><code>--max-quarantined &lt;n&gt;</code></td><td>Fail when more than <em>n</em> tests are quarantined</td></tr><tr><td><code>--fail-on-new-cluster</code></td><td>Fail when this run introduced a new failure cluster</td></tr><tr><td><code>--fail-on-flaky</code></td><td>Fail when this run contains any flaky test</td></tr><tr><td><code>--require-selection &lt;key&gt;</code></td><td>Fail when a test the named selection matches did not run or failed</td></tr><tr><td><code>--max-uncovered-changes &lt;n&gt;</code></td><td>Warn when more than <em>n</em> changed files have no observed test reach (warn-only — never fails the gate)</td></tr><tr><td><code>--json</code></td><td>Print the raw result as JSON instead of a summary</td></tr><tr><td><code>-h</code>, <code>--help</code></td><td>Show help</td></tr></tbody></table><p>The run source is resolved first-match-wins: <code>--run-id</code>, then <code>--from-file</code>, then <code>PIWI_OUTPUT_FILE</code>, then <code>./piwi-run.json</code>. At least one policy rule is required.</p><h2 id="report" tabindex="-1"><code>report</code> <a class="header-anchor" href="#report" aria-label="Permalink to &quot;`report`&quot;">​</a></h2><p>Print a <a href="/features/quality-reports.html">quality report</a> from the dashboard, so a CI scheduler can post it every week. It calls the report endpoint with the API key; the scope and the dashboard are the ones the <em>Export</em> dialog offers.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> report</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --period</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 7d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> md</span></span></code></pre></div><p><strong>Exit codes:</strong> <code>0</code> written · <code>1</code> written, and the verdict is at or below <code>--fail-on</code> · <code>2</code> no report.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Description</th></tr></thead><tbody><tr><td><code>--server-url &lt;url&gt;</code></td><td>Dashboard URL (env <code>PIWI_DASHBOARD_URL</code>)</td></tr><tr><td><code>--api-key &lt;key&gt;</code></td><td>API key (env <code>PIWI_API_KEY</code>)</td></tr><tr><td><code>--project &lt;names&gt;</code></td><td>Comma-separated project names or ids (default: every project the key can see)</td></tr><tr><td><code>--period &lt;period&gt;</code></td><td><code>7d</code>, <code>30d</code> (default), <code>last-month</code>, <code>this-quarter</code>, <code>2026-08-01..2026-08-31</code>, …</td></tr><tr><td><code>--compare &lt;mode&gt;</code></td><td><code>previous</code> (default), <code>year</code> or <code>none</code></td></tr><tr><td><code>--dashboard &lt;name&gt;</code></td><td><code>executive</code> (default), <code>engineering</code> or <code>overview</code></td></tr><tr><td><code>--branch &lt;names&gt;</code> / <code>--environment &lt;names&gt;</code></td><td>Narrow the runs (default: each project&#39;s default branch)</td></tr><tr><td><code>--selection &lt;key&gt;</code></td><td>Only the tests of this <a href="/features/test-selection.html">selection</a></td></tr><tr><td><code>--lang &lt;en|fr&gt;</code></td><td>Report language</td></tr><tr><td><code>--format &lt;fmt&gt;</code></td><td><code>md</code> (default), <code>json</code>, <code>html</code>, <code>pdf</code>, <code>csv</code></td></tr><tr><td><code>--output &lt;file&gt;</code></td><td>Write to a file instead of stdout (required for <code>pdf</code>)</td></tr><tr><td><code>--fail-on &lt;tone&gt;</code></td><td><code>bad</code>: exit 1 on a bad verdict; <code>mixed</code>: on a mixed or bad one</td></tr><tr><td><code>-h</code>, <code>--help</code></td><td>Show help</td></tr></tbody></table><h2 id="select-run" tabindex="-1"><code>select</code> / <code>run</code> <a class="header-anchor" href="#select-run" aria-label="Permalink to &quot;`select` / `run` {#select-run}&quot;">​</a></h2><p>Resolve a saved <a href="/features/test-selection.html">test selection</a> to the tests it matches. <code>select</code> prints the Playwright args (so you can compose them yourself); <code>run</code> executes <code>playwright test</code> with them. <code>run impact --base &lt;ref&gt;</code> runs the tests your working-tree diff impacts.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> select</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smoke</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smoke</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workers=4</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> impact</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --base</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin/main</span></span></code></pre></div><p><strong>Exit codes:</strong> <code>0</code> ok · <code>1</code> the test run failed (<code>run</code> only) · <code>2</code> could not resolve.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Description</th></tr></thead><tbody><tr><td><code>--server-url &lt;url&gt;</code></td><td>Dashboard URL (env <code>PIWI_DASHBOARD_URL</code>)</td></tr><tr><td><code>--api-key &lt;key&gt;</code></td><td>API key (env <code>PIWI_API_KEY</code>)</td></tr><tr><td><code>--project &lt;name|id&gt;</code></td><td>Project (env <code>PIWI_PROJECT_NAME</code>)</td></tr><tr><td><code>--format &lt;fmt&gt;</code></td><td><code>args</code> (<code>file:line</code>, default) · <code>grep</code> · <code>files</code> · <code>json</code></td></tr><tr><td><code>--budget &lt;duration&gt;</code></td><td>Cap total time, e.g. <code>5m</code>, <code>90s</code>, <code>300000</code> (ms)</td></tr><tr><td><code>--shard &lt;i/n&gt;</code></td><td>Keep only shard <em>i</em> of <em>n</em>, balanced by test duration and lock-aware (a lock&#39;s holders stay in one shard)</td></tr><tr><td><code>--fail-fast</code></td><td>Order the least-reliable tests first</td></tr><tr><td><code>--base &lt;ref&gt;</code></td><td>For <code>impact</code>: the ref to diff the working tree against</td></tr><tr><td><code>--strict</code></td><td>Fail (exit 2) instead of falling back when unreachable</td></tr><tr><td><code>--pkg-runner &lt;cmd&gt;</code></td><td>Package runner for the printed command (default <code>npx</code>)</td></tr><tr><td><code>--json</code></td><td>Print the full resolution as JSON (<code>select</code> only)</td></tr><tr><td><code>-h</code>, <code>--help</code></td><td>Show help</td></tr></tbody></table><p>Pass extra Playwright arguments after <code>--</code>: <code>piwi run smoke -- --headed --workers=1</code>.</p><p>When <code>run</code> spawns Playwright and the target config has <strong>no Piwi reporter</strong>, it appends <code>--add-reporter @piwitests/reporter</code> so the run still reaches the dashboard — provided the installed Playwright is <strong>1.63 or later</strong> (the version that added the flag; it appends to the configured reporters rather than replacing them). It logs one line naming what it added. On older Playwright it logs that the reporter is not configured and runs as before. This trial append gives you results, traces and screenshots but not the <a href="/guide/capture-fixtures.html">capture fixtures</a> or <a href="/guide/reporter.html#installing-via-wrapconfig"><code>wrapConfig</code></a> defaults — wire the reporter into the config (via <a href="#init"><code>init</code></a>) for the full set. A config that already lists the reporter is left untouched.</p><h2 id="probe" tabindex="-1"><code>probe</code> <a class="header-anchor" href="#probe" aria-label="Permalink to &quot;`probe`&quot;">​</a></h2><p>Run the dashboard&#39;s <a href="/features/probes.html">probe plan</a> and record what the suite noticed. <code>probe</code> fetches the (test, route, fault) pairs the dashboard wants checked, runs <code>playwright test</code> with the <a href="/guide/capture-fixtures.html">capture fixtures</a> in probe mode — each fault injected at the network boundary, one per test — and posts the outcomes back. The run is stamped as a probe run, so the dashboard never counts it as a real run (no clusters, regression signals, notifications or PR feedback), and retries are forced off.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> probe</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Flag</th><th>Description</th></tr></thead><tbody><tr><td><code>--server-url &lt;url&gt;</code></td><td>Dashboard URL (env <code>PIWI_DASHBOARD_URL</code>)</td></tr><tr><td><code>--api-key &lt;key&gt;</code></td><td>API key (env <code>PIWI_API_KEY</code>)</td></tr><tr><td><code>--project &lt;name|id&gt;</code></td><td>Project name or id (env <code>PIWI_PROJECT_NAME</code>)</td></tr><tr><td><code>--budget &lt;n&gt;</code></td><td>Max pairs to probe this run (default the server&#39;s)</td></tr><tr><td><code>-h</code>, <code>--help</code></td><td>Show help</td></tr></tbody></table><p>Everything after <code>--</code> is passed to <code>playwright test</code>. A probed test fails by design when it notices the injected fault, so a non-zero Playwright exit is expected and is not a command error.</p><h2 id="ai" tabindex="-1"><code>ai</code> <a class="header-anchor" href="#ai" aria-label="Permalink to &quot;`ai`&quot;">​</a></h2><p>Manage committed natural-language <a href="/features/ai-steps.html">AI-step</a> artifacts (<code>page.piwiLocator(...)</code> / <code>page.piwiRun(...)</code>). The LLM authors each entry once; CI replays the committed JSON deterministically with no model calls, so these commands are how you keep the committed set healthy.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ai</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ai</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> resolve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;checkout&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ai</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prune</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Subcommand</th><th>What it does</th></tr></thead><tbody><tr><td><code>check</code></td><td>Scan committed entries for orphans, non-canonical files and duplicate templates. Read-only; exits <code>1</code> when issues are found</td></tr><tr><td><code>resolve</code></td><td>Author missing entries by running the suite in resolve mode against the configured authoring server (forces <code>--workers=1</code>)</td></tr><tr><td><code>prune</code></td><td>Delete orphaned/dormant entries</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Flag</th><th>Applies to</th><th>Description</th></tr></thead><tbody><tr><td><code>--dir &lt;name&gt;</code></td><td><code>check</code></td><td>Entry directory name per spec (env <code>PIWI_AI_DIR</code>, default <code>__piwi__</code>)</td></tr><tr><td><code>--cwd &lt;path&gt;</code></td><td><code>check</code></td><td>Root to scan (default: current directory)</td></tr><tr><td><code>--json</code></td><td><code>check</code></td><td>Emit findings as JSON</td></tr><tr><td><code>--grep &lt;re&gt;</code></td><td><code>resolve</code></td><td>Only author entries for matching tests</td></tr><tr><td><code>--project &lt;name&gt;</code></td><td><code>resolve</code></td><td>Author under one Playwright project (a resolve profile)</td></tr><tr><td><code>--env K=V</code></td><td><code>resolve</code></td><td>Extra env for the run (repeatable — flags/viewport profiles)</td></tr><tr><td><code>--update-ai</code></td><td><code>resolve</code></td><td>Re-author entries that already exist (needs <code>PIWI_DASHBOARD_URL</code> / <code>PIWI_API_KEY</code>)</td></tr></tbody></table><p><strong>Exit codes:</strong> <code>0</code> clean (or <code>--help</code>) · <code>1</code> hygiene issues found · <code>2</code> bad arguments / command unavailable.</p><h2 id="codegen" tabindex="-1"><code>codegen</code> <a class="header-anchor" href="#codegen" aria-label="Permalink to &quot;`codegen`&quot;">​</a></h2><p>Turn a <a href="/reference/steps-format.html">steps file</a> into a Playwright spec. Piwi Picker saves one with <a href="/features/extension.html#record-actions"><strong>Download steps</strong></a>. The spec is written for a test project: URLs on the recorded site become paths, so your config&#39;s <code>baseURL</code> applies; each element uses the first of its recorded locators that the <a href="/reference/locator-stability.html">stability rules</a> call stable; and after each step that leads to another page, the spec waits for that page&#39;s URL. Nothing is sent anywhere unless a project is configured.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codegen</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> steps.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/checkout.spec.ts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test-import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./fixtures</span></span></code></pre></div><p><code>codegen bug:&lt;id&gt;</code> reads the steps of a <a href="/features/bug-reports.html">bug report</a> from the dashboard (<code>--server-url</code>) instead of a file.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Description</th></tr></thead><tbody><tr><td><code>--out &lt;file&gt;</code></td><td>Write the spec to this file instead of printing it; an existing file is kept unless <code>--force</code></td></tr><tr><td><code>--force</code></td><td>Replace the file <code>--out</code> names</td></tr><tr><td><code>--body</code></td><td>Print only the test&#39;s lines, to paste into an existing test, with the imports they need as comments</td></tr><tr><td><code>--title &lt;text&gt;</code></td><td>Test title (default: the steps file&#39;s own title)</td></tr><tr><td><code>--test-import &lt;mod&gt;</code></td><td>Module <code>test</code> and <code>expect</code> are imported from, such as your fixtures file (default <code>@playwright/test</code>)</td></tr><tr><td><code>--absolute-urls</code></td><td>Keep the recorded URLs instead of paths</td></tr><tr><td><code>--no-url-checks</code></td><td>Do not wait for each new page&#39;s URL</td></tr><tr><td><code>--env-values</code></td><td>Read every typed value from a <code>PIWI_TEST_VALUE_&lt;n&gt;</code> environment variable instead of writing it into the spec</td></tr><tr><td><code>--fail</code></td><td>Mark the test as expected to fail (<code>test.fail()</code>)</td></tr><tr><td><code>--fail-reason &lt;text&gt;</code></td><td>The reason written beside <code>test.fail()</code>, such as a ticket key</td></tr><tr><td><code>--tag &lt;tag&gt;</code></td><td>Add a tag; repeat for more (<code>@</code> is added when missing)</td></tr><tr><td><code>--project &lt;name|id&gt;</code></td><td>Project (env <code>PIWI_PROJECT_NAME</code>): its <a href="/features/test-functions.html">function catalog</a> turns matching steps into calls to your own functions, and a locator your tests already use is preferred when it is not brittle</td></tr><tr><td><code>--server-url &lt;url&gt;</code></td><td>Dashboard URL (env <code>PIWI_DASHBOARD_URL</code>)</td></tr><tr><td><code>--api-key &lt;key&gt;</code></td><td>API key (env <code>PIWI_API_KEY</code>)</td></tr><tr><td><code>--offline</code></td><td>Do not contact the dashboard, even when one is configured</td></tr><tr><td><code>-h</code>, <code>--help</code></td><td>Show help</td></tr></tbody></table><p>Warnings go to stderr, one per step worth a look: a password read from the environment, an element with no locator, or one whose best locator is brittle. A dashboard that cannot be reached only costs the catalog and the preferred locators; the spec is still written.</p><p><strong>Exit codes:</strong> <code>0</code> written or printed · <code>2</code> the steps file could not be read or checked, or the spec could not be written.</p><h2 id="preflight" tabindex="-1"><code>preflight</code> <a class="header-anchor" href="#preflight" aria-label="Permalink to &quot;`preflight`&quot;">​</a></h2><p>List the test locators a change breaks, before it runs: <a href="/features/preflight.html">Locator preflight</a> explains what it reads and how it matches. It diffs the working tree against a ref, compares the strings the diff removes or renames with the project&#39;s locator index, and prints each broken chain with its tests, its call sites and its rewrite.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preflight</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preflight</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --base</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @{upstream}</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --strict</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preflight</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fix</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workers=2</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Flag</th><th>Description</th></tr></thead><tbody><tr><td><code>--base &lt;ref&gt;</code></td><td>Diff the working tree against this ref (default <code>HEAD</code>: uncommitted changes)</td></tr><tr><td><code>--branch &lt;name&gt;</code></td><td>Compare with this branch&#39;s locator index (default: the project&#39;s default branch)</td></tr><tr><td><code>--test-root &lt;dir&gt;</code></td><td>Where call sites resolve (default: the directory of the nearest <code>playwright.config</code>)</td></tr><tr><td><code>--locale &lt;code&gt;</code></td><td>Translation files of this locale resolve keys first (default <code>en</code>)</td></tr><tr><td><code>--fix</code></td><td>Write the rewrites into the call sites whose line holds the string</td></tr><tr><td><code>--run</code></td><td>Run the tests that reach the changed files and the specs of the broken locators; Playwright arguments go after <code>--</code></td></tr><tr><td><code>--strict</code></td><td>Exit 1 when a likely break is left unfixed</td></tr><tr><td><code>--server-url &lt;url&gt;</code></td><td>Dashboard URL (env <code>PIWI_DASHBOARD_URL</code>, then <code>.env</code>, then the running desktop app)</td></tr><tr><td><code>--api-key &lt;key&gt;</code></td><td>API key (env <code>PIWI_API_KEY</code>)</td></tr><tr><td><code>--project &lt;name|id&gt;</code></td><td>Project (env <code>PIWI_PROJECT_NAME</code>)</td></tr><tr><td><code>--json</code></td><td>Print the breaks, their call sites, the edits and the impact as JSON</td></tr><tr><td><code>-h</code>, <code>--help</code></td><td>Show help</td></tr></tbody></table><p>The index is cached in <code>.piwi/locator-index.json</code> per dashboard, project and branch, and used when the dashboard cannot be reached.</p><p><strong>Exit codes:</strong> <code>0</code> ok, breaks or not · <code>1</code> a likely break left unfixed with <code>--strict</code>, or <code>--run</code>&#39;s tests failed · <code>2</code> the index could not be fetched and there is no cached copy, or the diff could not be read.</p><h2 id="bug" tabindex="-1"><code>bug</code> <a class="header-anchor" href="#bug" aria-label="Permalink to &quot;`bug`&quot;">​</a></h2><p>Get a <a href="/features/bug-reports.html">bug report</a>&#39;s failing test from the dashboard, written with the project&#39;s <a href="/features/bug-reports.html#the-failing-test">generated specs settings</a>: <code>test.fail()</code> while the bug exists, <code>@bug</code>, and <code>piwi:bug &lt;id&gt;</code> so the report follows its runs. Printed by default; <code>--write</code> puts it in the project&#39;s bugs folder (<code>tests/bugs</code> unless the project names another) and runs it once with <code>playwright test</code>, so you see the bug reproduce before you fix it.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bug</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 37</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --write</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Flag</th><th>Description</th></tr></thead><tbody><tr><td><code>--write</code></td><td>Write the spec to the project&#39;s bugs folder (from the repository root), then run it once</td></tr><tr><td><code>--out &lt;file&gt;</code></td><td>Write it to this file instead, then run it once; its test import is written for that file&#39;s folder</td></tr><tr><td><code>--no-run</code></td><td>With <code>--write</code> or <code>--out</code>: write it without running it</td></tr><tr><td><code>--force</code></td><td>Replace an existing file</td></tr><tr><td><code>--run-mode</code></td><td>The spec without <code>test.fail()</code>, as a reproduction runs it</td></tr><tr><td><code>--server-url &lt;url&gt;</code></td><td>Dashboard URL (env <code>PIWI_DASHBOARD_URL</code>)</td></tr><tr><td><code>--api-key &lt;key&gt;</code></td><td>API key (env <code>PIWI_API_KEY</code>)</td></tr><tr><td><code>-h</code>, <code>--help</code></td><td>Show help</td></tr></tbody></table><p><strong>Exit codes:</strong> <code>0</code> printed or written, and when run, the test failed on the bug as <code>test.fail()</code> expects · <code>1</code> the run did not: the bug may be fixed, or a step no longer matches the page · <code>2</code> the report could not be read or the file could not be written.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/guide/getting-started.html">Getting started</a> — <code>init</code> in the setup flow</li><li><a href="/guide/ci.html">CI &amp; sharding</a> — <code>gate</code> in a CI job, and the run output file</li><li><a href="/features/test-selection.html">Test selections</a> — what <code>select</code> / <code>run</code> resolve</li><li><a href="/features/ai-steps.html">AI steps</a> — the authoring/replay lifecycle <code>ai</code> manages</li><li><a href="/features/agent-skills.html">Agent skills</a>: what <code>skills</code> installs and what each skill does</li></ul>',66)])])}const k=e(o,[["render",i]]);export{g as __pageData,k as default};
